  ('ac931ac1-955d-4d58-88d0-102aa358e7e8', 'f4893692-2623-420f-845d-8bec16fd4479', 'Omkar V.', 4, 'We keep reordering the same two plates: the Malaka Special mutton chops and the Chicken Thigh Thai.', '2026-06-14', 'Zomato'),
  ('69cd4e69-8746-4268-8fa6-72f958afcca6', 'f4893692-2623-420f-845d-8bec16fd4479', 'Shruti A.', 3, 'Vegetarians have very little to choose from on a menu built around meat and seafood.', '2026-05-02', 'Zomato'),
  ('e6ea02b9-0885-484b-8ae8-c42cc1bfc6de', 'f4893692-2623-420f-845d-8bec16fd4479', 'Mandar T.', 2, 'Portion sizes and seasoning were not the same on my two visits.', '2026-04-19', 'Zomato'),
  ('952af3c8-903f-4e19-848c-8c6b4ad48311', 'f4893692-2623-420f-845d-8bec16fd4479', 'Ishita L.', 1, 'The kitchen was slow - a long wait between ordering and the first plate.', '2026-03-08', 'Zomato')
