  ('d60a2b89-d783-4c7c-8afc-abc69167283d', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Mysore Ghee Masala Dosa', 'main', 1, 'Mysore masala dosa cooked in ghee; cheaper than the namesake Vaishali ghee dosa.', 167, true, true),
