  ('59a80f23-0c14-4c6d-8d54-669d0367859c', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Upma', 'starter', 1, 'Menu prints a serving window of 7:00 a.m. to 10:00 a.m. against this item.', 57, true, false),
  ('9113d2fa-1b10-40a5-83ac-ec9617a699fe', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Idli Sambar / Chatni', 'starter', 2, 'Idli with sambar or chutney; the menu spells chutney as ''chatni'', and dahi idli is 124.', 76, true, false),
  ('9c862bde-4b25-4f78-89f0-f5994d9bdace', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Dahi Puri', 'starter', 3, 'Chaat counter item; the whole Bhel Puri section on the menu is timed 5:00 p.m. to 10:30 p.m.', 110, true, false),
  ('54f42622-75a3-45ff-8159-816c8cee87a4', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Bhel Puri', 'starter', 4, 'From the chaat section served only 5:00 p.m. to 10:30 p.m.; plain bhel is 100.', 110, true, false),
  ('c1e6a241-447a-4b5f-8caa-99440db7890a', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Sev Puri', 'starter', 5, 'Chaat section item; the shev-potato-puri and dahi-bhel variants are the same price.', 110, true, false),
  ('7271e08d-7e7f-47b6-8a15-7301245362b8', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Thandai Shake', 'beverage', 1, 'Thandai-flavoured shake, priced the same as the apple shake; vanilla ice cream can be added to any shake.', 167, true, false),
  ('b8678676-cf14-4310-8291-489cdaaf97eb', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Cold Coffee', 'beverage', 2, 'Cheapest item in the shakes block, which runs 152 to 180.', 152, true, false),
  ('261f8eba-75a8-4677-8086-1837cd98d71a', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Mango Lassi', 'beverage', 3, 'Sweet lassi; the regular lassi (sweet or salted) is 124.', 167, true, false),
  ('ba12189e-533b-45e4-89f6-03132b97b6bc', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Kulfi', 'dessert', 1, 'From the ice-creams block, where scoops start at 86 and kesar pista is 102.', 97, true, false)
