  ('ff0c7474-7381-4680-8eb2-74e126960bd9', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Aditya S.', 5, 'My default South Indian spot on FC Road since I moved to Pune - always crowded, and I end up on the ghee dosa, idlis and filter coffee every time.', '2026-02-20', 'Zomato'),
  ('efacda8d-b9fa-44a2-8cd5-3227cd05e8f6', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Rutuja L.', 5, 'one special dosa is large enough for two people; expect a crowd and plan the visit around it.', '2026-09-02', 'Zomato'),
  ('2a0fa383-224a-4b78-86f1-98765207bd53', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Sanika M.', 5, 'a 20-year regular: idli, dosa and uttapam taste the same as ever, only the menu-card rates have changed.', '2026-03-09', 'Zomato'),
  ('7bab709a-74a0-4e0b-898c-130538988258', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Shruti A.', 3, 'only the Mysore masala dosa is worth ordering; everything else is average and the online hype outruns the plate.', '2026-06-22', 'Zomato'),
  ('d221ce41-f388-473b-861b-b5bde295f677', '910563e5-fb74-4864-89fc-5a808a95ed0d', 'Rohan D.', 3, 'The sambar was purely tangy and the chutney tasteless for me; quality feels lower than the years I used to come here.', '2026-08-16', 'Zomato'),
